// What is true now, per patient per consent type. Derived from CONSENT_GRANTED/CONSENT_REVOKED (CP36).
type ReadPatientConsent struct {
	PatientID          uuid.UUID
	FacilityID         uuid.UUID
	ConsentType        string
	Status             string
	TemplateVersion    int32
	Language           string
	TemplateDigest     string
	CaptureMethod      string
	EvidenceKey        string
	EvidenceSha256     string
	PaperReference     string
	WitnessedBy        uuid.NullUUID
	WitnessedByCode    string
	GrantedForRelation string
	GrantedForName     string
	GrantedAt          time.Time
	GrantedBy          uuid.UUID
	GrantedByCode      string
	RevokedAt          *time.Time
	RevokedBy          uuid.NullUUID
	RevokedByCode      string
	RevokeReason       string
	RevokeRequestedBy  string
	EventID            uuid.UUID
	GlobalSeq          int64
}

// Every grant and revocation in order, so "was this lawful at the time" is answerable (CP36).
type ReadPatientConsentEvent struct {
	ID              int64
	PatientID       uuid.UUID
	FacilityID      uuid.UUID
	ConsentType     string
	Action          string
	TemplateVersion *int32
	Language        string
	CaptureMethod   string
	Reason          string
	RequestedBy     string
	ActorID         uuid.UUID
	ActorCode       string
	OccurredAt      time.Time
	EventID         uuid.UUID
	GlobalSeq       int64
}

// The demographic change history, derived from PATIENT_DEMOGRAPHICS_CORRECTED. The originals are in the ledger (CP35).
type ReadPatientCorrection struct {
	ID              int64
	PatientID       uuid.UUID
	FacilityID      uuid.UUID
	Field           string
	Previous        string
	Current         string
	Reason          string
	HighImpact      bool
	CorrectedBy     uuid.UUID
	CorrectedByCode string
	CorrectedAt     time.Time
	EventID         uuid.UUID
	GlobalSeq       int64
}

// Everything known about a patient, in one chronological shape, attributed per row (CP37, §8).
type ReadPatientTimeline struct {
	ID           int64
	PatientID    uuid.UUID
	FacilityID   uuid.UUID
	OccurredAt   time.Time
	RecordedAt   time.Time
	Category     string
	Kind         string
	LabelEn      string
	LabelBn      string
	Value        string
	Unit         string
	ValueNum     pgtype.Numeric
	ActorID      uuid.NullUUID
	ActorCode    string
	ActorRole    string
	ActorStation string
	DeviceID     uuid.NullUUID
	Source       string
	Flags        []string
	EventID      uuid.UUID
	EventType    string
	GlobalSeq    int64
	Item         string
	// The permission a reader needs. Filtering happens in SQL so a hidden row cannot skew a count or a cursor.
	NeedsPermission string
	SupersededBy    uuid.NullUUID
}

// Events a projection could not apply. The projection stays degraded until each is resolved (CP25).
type ReadProjectionDeadLetter struct {
	ID         int64
	Projection string
	GlobalSeq  int64
	EventID    uuid.UUID
	EventType  string
	Error      string
	Attempts   int32
	FailedAt   time.Time
	ResolvedAt *time.Time
	Resolution *string
}

// One row per projection: version, mode, how far it has got, and whether it is healthy (CP25).
type ReadProjectionState struct {
	Name       string
	Version    int32
	Mode       string
	Checkpoint int64
	Status     string
	AppliedAt  *time.Time
	UpdatedAt  time.Time
	RebuiltAt  *time.Time
}

// Per-station, per-day activity for the traffic board. Asynchronous projection (CP25).
type ReadStationActivity struct {
	FacilityID uuid.UUID
	ClinicDay  time.Time
	Station    string
	Events     int64
	LastSeq    int64
	UpdatedAt  time.Time
}

type ReadStationActivityVisit struct {
	FacilityID uuid.UUID
	ClinicDay  time.Time
	Station    string
	VisitID    uuid.UUID
}

// The current value of each measurement on a visit, with its attribution. Synchronous projection (CP25).
type ReadVisitVital struct {
	VisitID      uuid.UUID
	Code         string
	FacilityID   uuid.UUID
	PatientID    uuid.NullUUID
	Value        pgtype.Numeric
	Unit         string
	Value2       pgtype.Numeric
	TakenAt      time.Time
	RecordedAt   time.Time
	ActorUserID  uuid.UUID
	ActorRole    string
	ActorStation *string
	EventID      uuid.UUID
	GlobalSeq    int64
	Corrected    bool
}

// The consenting subjects, and the only thing dthcms_research may read. Consent is enforced by privilege (CP36).
type ResearchCohort struct {
	ResearchID         string
	FacilityCode       string
	EnrolledMonth      time.Time
	BirthYear          int16
	Sex                string
	EducationLevel     *string
	OccupationCategory *string
	IncomeBand         *string
	HouseholdSize      *int16
	ResidenceType      *string
	MedicinePayer      *string
	CreatedAt          time.Time
}

// The anonymised subject a researcher queries. Carries no identifier and no join path to core (CP28, §12).
type ResearchResearchSubject struct {
	// Opaque, from a cryptographic random source. Not derivable from the clinical id, and carrying no ordering.
	ResearchID         string
	FacilityCode       string
	EnrolledMonth      time.Time
	BirthYear          int16
	Sex                string
	EducationLevel     *string
	OccupationCategory *string
	IncomeBand         *string
	HouseholdSize      *int16
	ResidenceType      *string
	MedicinePayer      *string
	CreatedAt          time.Time
	// Opt-in, never assumed. False until a RESEARCH consent is granted, false again on revocation (CP36, D-02).
	ResearchConsent bool
}
